// Literal port of the team's Casa3DSDK (module animation/clotheslines). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installAnimationClotheslines(K: Kernel, shared: Shared): void {
  const { invalidate, CLOTHES_UNIFORMS } = K;
  // ---------------- 80 light animations ----------------
  // ===== light scenery animations: laundry swaying in the wind (time uniform; no per-frame allocation) =====
  const WIND = { t0: performance.now(), last: 0, base: 0.55 };
  function animateClotheslines(now) {
    if (!shared.ctx.clotheslines || !shared.ctx.clotheslines.length) return;
    if (now - WIND.last < 33) return; WIND.last = now; // ~30 frames/s is enough for cloth
    const t = (now - WIND.t0) / 1000;
    CLOTHES_UNIFORMS.uTime.value = t;
    CLOTHES_UNIFORMS.uVento.value = WIND.base + 0.45 * Math.sin(t * 0.23) * Math.sin(t * 0.11 + 1.3) + 0.25 * Math.max(0, Math.sin(t * 0.57)); // slow gusts
    const g = shared.ctx.parts && shared.ctx.parts['laundry_' + shared.ctx.clotheslines[0]];
    if (g) { let vis = true; for (let n = g; n; n = n.parent) if (!n.visible) { vis = false; break; } if (!vis) return; }
    invalidate();
  }
  Object.assign(K, { WIND, animateClotheslines });
}
